def _host_is_private(host):
    """True if host is missing, internal, or resolves to a private/loopback/
    link-local/reserved IP (blocks SSRF to cloud metadata + internal services)."""
    host = (host or "").strip().rstrip(".").lower()
    if not host or host == "localhost" or host.endswith((".localhost", ".internal", ".local")):
        return True
    try:
        infos = socket.getaddrinfo(host, None)
    except Exception:
        return True  # unresolvable -> treat as unsafe
    for info in infos:
        try:
            addr = ipaddress.ip_address(info[4][0])
        except ValueError:
            return True
        if (addr.is_private or addr.is_loopback or addr.is_link_local
                or addr.is_reserved or addr.is_multicast or addr.is_unspecified):
            return True
    return False


def safe_media_get(url, max_redirects=5, **kwargs):
    """requests.get for a client-supplied media URL, hardened against SSRF: https
    only, no host that resolves to an internal IP, and redirects followed
    MANUALLY so each hop is re-validated (a public URL can't 302 to metadata)."""
    kwargs["allow_redirects"] = False
    current = url
    for _ in range(max_redirects + 1):
        p = urlparse(current)
        if p.scheme != "https" or _host_is_private(p.hostname):
            raise ValueError("unsafe media url")
        resp = requests.get(current, **kwargs)
        if resp.status_code in (301, 302, 303, 307, 308) and resp.headers.get("Location"):
            current = urljoin(current, resp.headers["Location"])
            continue
        return resp
    raise ValueError("too many redirects")


def is_cancelled(job_id, app_url):
    """Has the user cancelled this render? Synchronous GET to the app server with
    a short timeout. FAIL-OPEN: returns False on any error / missing app_url, so a
    check failure (or a slow server) can never abort a legitimate render — the
    worst case is we render something the user tried to cancel."""
    if not job_id or not app_url:
        return False
    try:
        headers = {}
        _secret = os.environ.get("MODAL_CALLBACK_SECRET", "")
        if _secret:
            headers["X-Modal-Secret"] = _secret
        r = requests.get(
            f"{app_url}/api/render-cancelled",
            params={"job_id": job_id},
            headers=headers,
            timeout=3,
        )
        if r.status_code == 200:
            return r.json().get("cancelled") is True
    except Exception:
        pass
    return False

