def clamp(val, lo, hi):
    return max(lo, min(hi, val))


def detect_face_positions(video_path, sample_timestamps):
    """
    Sample frames at given timestamps and detect the dominant face position.
    Uses OpenCV's DNN-based face detector (ResNet SSD) which is far more
    reliable than Haar cascades — handles angled faces, glasses, hats,
    varying skin tones, and low light.
    Returns list of {"t", "cx", "cy", "found"} entries.
    """
    import cv2

    cap = cv2.VideoCapture(video_path)
    if not cap.isOpened():
        print("[reframe] Could not open video for face detection", flush=True)
        return []

    frame_w = int(cap.get(cv2.CAP_PROP_FRAME_WIDTH) or 0)
    frame_h = int(cap.get(cv2.CAP_PROP_FRAME_HEIGHT) or 0)
    center_x = frame_w // 2 if frame_w > 0 else 540
    center_y = frame_h // 2 if frame_h > 0 else 960

    # Load DNN face detector (ResNet-10 SSD, trained on WIDER FACE dataset)
    PROTOTXT = "/models/face_detector/deploy.prototxt"
    CAFFEMODEL = "/models/face_detector/res10_300x300_ssd_iter_140000.caffemodel"
    use_dnn = os.path.exists(PROTOTXT) and os.path.exists(CAFFEMODEL)

    net = None
    face_cascade = None
    if use_dnn:
        net = cv2.dnn.readNetFromCaffe(PROTOTXT, CAFFEMODEL)
        print("[reframe] Using DNN face detector (ResNet SSD)", flush=True)
    else:
        # Fallback to Haar cascade if model files not available
        face_cascade = cv2.CascadeClassifier(
            cv2.data.haarcascades + "haarcascade_frontalface_default.xml"
        )
        print("[reframe] WARNING: DNN model not found, falling back to Haar cascade", flush=True)

    # Track last known face position for temporal smoothing
    last_cx, last_cy = center_x, center_y
    CONFIDENCE_THRESHOLD = 0.5

    positions = []
    for t in sample_timestamps:
        cap.set(cv2.CAP_PROP_POS_MSEC, float(t) * 1000.0)
        ret, frame = cap.read()
        if not ret or frame is None:
            positions.append({"t": float(t), "cx": last_cx, "cy": last_cy, "found": False})
            continue

        found = False
        best_cx, best_cy = center_x, center_y
        best_conf = 0.0

        if use_dnn:
            h, w = frame.shape[:2]
            blob = cv2.dnn.blobFromImage(
                cv2.resize(frame, (300, 300)), 1.0, (300, 300),
                (104.0, 177.0, 123.0), swapRB=False, crop=False
            )
            net.setInput(blob)
            detections = net.forward()

            best_area = 0
            for det_i in range(detections.shape[2]):
                confidence = float(detections[0, 0, det_i, 2])
                if confidence < CONFIDENCE_THRESHOLD:
                    continue
                x1 = int(detections[0, 0, det_i, 3] * w)
                y1 = int(detections[0, 0, det_i, 4] * h)
                x2 = int(detections[0, 0, det_i, 5] * w)
                y2 = int(detections[0, 0, det_i, 6] * h)
                area = (x2 - x1) * (y2 - y1)
                # Pick the largest face with highest confidence
                if confidence > best_conf or (confidence > CONFIDENCE_THRESHOLD and area > best_area):
                    best_conf = confidence
                    best_area = area
                    best_cx = (x1 + x2) // 2
                    best_cy = (y1 + y2) // 2
                    found = True
        else:
            gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
            faces = face_cascade.detectMultiScale(gray, scaleFactor=1.1, minNeighbors=5, minSize=(80, 80))
            if len(faces) > 0:
                fx, fy, fw, fh = max(faces, key=lambda f: f[2] * f[3])
                best_cx = int(fx + fw // 2)
                best_cy = int(fy + fh // 2)
                found = True

        if found:
            last_cx, last_cy = best_cx, best_cy

        positions.append({
            "t": float(t),
            "cx": best_cx if found else last_cx,
            "cy": best_cy if found else last_cy,
            "found": found,
            "confidence": best_conf if found else 0.0,
        })

    cap.release()
    found_count = sum(1 for p in positions if p["found"])
    print(f"[reframe] Detected faces in {found_count}/{len(positions)} sampled frames", flush=True)
    return positions


def detect_face_positions_dense(video_path, every_n_frames=5, target_w=None, target_h=None):
    """
    Dense face detection using FFmpeg frame extraction + OpenCV DNN.
    FFmpeg extracts every Nth frame with GPU decode (NVDEC) — much faster
    than OpenCV's sequential read/grab loop which must decode all h264 frames.

    target_w/target_h: if set, scale coordinates to this resolution (e.g., when
    running on a low-res proxy but need coords in original source resolution).

    Returns list of {"t": float, "cx": float, "cy": float, "found": bool, "confidence": float}.
    """
    import cv2

    # Probe video metadata without decoding
    _probe = subprocess.run(
        ["ffprobe", "-v", "quiet", "-print_format", "json", "-show_streams", video_path],
        capture_output=True, text=True, timeout=5,
    )
    _streams = json.loads(_probe.stdout or "{}").get("streams", [])
    _vs = next((s for s in _streams if s.get("codec_type") == "video"), {})
    fps = float(eval(_vs.get("r_frame_rate", "30/1")))
    frame_count = int(_vs.get("nb_frames", 0)) or int(float(_vs.get("duration", "0")) * fps)
    frame_w = int(_vs.get("width", 0)) or 1080
    frame_h = int(_vs.get("height", 0)) or 1920

    # Output resolution for face coordinates
    _out_w = target_w or frame_w
    _out_h = target_h or frame_h

    # Extract at native resolution if source is already small (e.g., 240p proxy),
    # otherwise extract at 540p for speed
    _extract_h = min(540, frame_h)
    _scale = _out_h / _extract_h if _extract_h > 0 else 1.0
    _extract_w = round(frame_w * _extract_h / frame_h) if frame_h > 0 else round(_out_w * _extract_h / _out_h)
    center_x = _out_w // 2
    center_y = _out_h // 2

    PROTOTXT = "/models/face_detector/deploy.prototxt"
    CAFFEMODEL = "/models/face_detector/res10_300x300_ssd_iter_140000.caffemodel"
    if not (os.path.exists(PROTOTXT) and os.path.exists(CAFFEMODEL)):
        print("[dense-face] DNN model not found, cannot run dense detection", flush=True)
        return []

    net = cv2.dnn.readNetFromCaffe(PROTOTXT, CAFFEMODEL)
    CONFIDENCE_THRESHOLD = 0.5

    _t_start = time.time()

    # Extract every Nth frame at reduced resolution using FFmpeg with GPU decode.
    # This is 5-10x faster than OpenCV's grab()/read() loop because:
    # 1. NVDEC hardware decode (vs CPU h264 decode)
    # 2. Only outputs frames we need (vs decoding all frames sequentially)
    # 3. Downscale happens on GPU or during decode (less memory bandwidth)
    _extract_dir = os.path.join(os.path.dirname(video_path) or "/tmp", "_face_frames")
    os.makedirs(_extract_dir, exist_ok=True)
    _hw_args = ["-hwaccel", "cuda"] if _HAS_HWACCEL else []
    _extract_cmd = subprocess.run(
        ["ffmpeg", "-y", "-v", "warning"] + _hw_args + [
            "-i", video_path,
            "-vf", f"select=not(mod(n\\,{every_n_frames})),scale={_extract_w}:{_extract_h}",
            "-vsync", "0", "-q:v", "2",
            os.path.join(_extract_dir, "face_%04d.jpg"),
        ],
        capture_output=True, text=True, timeout=30,
    )
    if _extract_cmd.returncode != 0:
        raise RuntimeError(
            f"FFmpeg face-frame extraction failed (rc={_extract_cmd.returncode}): "
            f"{(_extract_cmd.stderr or '')[-300:]}"
        )

    _extract_elapsed = time.time() - _t_start
    _frame_files = sorted(glob.glob(os.path.join(_extract_dir, "face_*.jpg")))
    if not _frame_files:
        print("[dense-face] No frames extracted", flush=True)
        return []

    # Run DNN on extracted frames
    last_cx, last_cy = center_x, center_y
    positions = []

    for _fi, _fpath in enumerate(_frame_files):
        frame_idx = _fi * every_n_frames
        t_sec = frame_idx / fps
        frame = cv2.imread(_fpath)
        if frame is None:
            continue

        h, w = frame.shape[:2]
        blob = cv2.dnn.blobFromImage(
            cv2.resize(frame, (300, 300)), 1.0, (300, 300),
            (104.0, 177.0, 123.0), swapRB=False, crop=False
        )
        net.setInput(blob)
        detections = net.forward()

        found = False
        best_cx, best_cy = center_x, center_y
        best_w, best_h = 0, 0
        best_conf = 0.0
        best_area = 0

        for det_i in range(detections.shape[2]):
            confidence = float(detections[0, 0, det_i, 2])
            if confidence < CONFIDENCE_THRESHOLD:
                continue
            # Coordinates are in extract resolution — scale back to original
            x1 = int(detections[0, 0, det_i, 3] * w * _scale)
            y1 = int(detections[0, 0, det_i, 4] * h * _scale)
            x2 = int(detections[0, 0, det_i, 5] * w * _scale)
            y2 = int(detections[0, 0, det_i, 6] * h * _scale)
            area = (x2 - x1) * (y2 - y1)
            if confidence > best_conf or (confidence > CONFIDENCE_THRESHOLD and area > best_area):
                best_conf = confidence
                best_area = area
                best_cx = (x1 + x2) // 2
                best_cy = (y1 + y2) // 2
                best_w = x2 - x1
                best_h = y2 - y1
                found = True

        if found:
            last_cx, last_cy = best_cx, best_cy

        positions.append({
            "t": round(t_sec, 4),
            "cx": float(best_cx if found else last_cx),
            "cy": float(best_cy if found else last_cy),
            "found": found,
            "confidence": round(best_conf, 4) if found else 0.0,
            # Face bbox dimensions (target-canvas px). These enable real
            # shot_scale (wide/medium/close) in _build_face_signals — the
            # detector previously dropped them, so the median bbox width was
            # always 0 and the label collapsed to a constant. 0 when no face
            # this frame. Premium-gated consumer; the free path ignores these.
            "w": float(best_w) if found else 0.0,
            "h": float(best_h) if found else 0.0,
        })

    # Cleanup extracted frames
    for _f in _frame_files:
        try:
            os.remove(_f)
        except OSError:
            pass
    try:
        os.rmdir(_extract_dir)
    except OSError:
        pass

    elapsed = time.time() - _t_start
    found_count = sum(1 for p in positions if p["found"])
    print(
        f"[dense-face] {found_count}/{len(positions)} detections in {elapsed:.2f}s "
        f"({frame_count} total frames, every {every_n_frames}th @ {fps:.1f}fps, extracted at {_extract_w}x{_extract_h})",
        flush=True,
    )
    return positions


def smooth_face_trajectory(detections, total_duration=0.0, alpha=0.15):
    """
    Apply exponential moving average to dense face detections for buttery
    smooth camera movement.  Gaps (found=False) coast on the last known
    smoothed position.

    Returns a new list with the same structure but smoothed cx/cy values.
    """
    if not detections:
        return []

    smoothed = []
    sx, sy = None, None

    for det in detections:
        cx = float(det.get("cx", 540.0))
        cy = float(det.get("cy", 960.0))
        found = det.get("found", False)

        if sx is None:
            # Initialise with first position
            sx, sy = cx, cy
        else:
            if found:
                sx = alpha * cx + (1.0 - alpha) * sx
                sy = alpha * cy + (1.0 - alpha) * sy
            # else: coast — sx/sy stay unchanged

        smoothed.append({
            "t": det["t"],
            "cx": round(sx, 2),
            "cy": round(sy, 2),
            "found": found,
            "confidence": det.get("confidence", 0.0),
        })

    return smoothed


def _face_position_at(trajectory, t_seconds, canvas_w=1080, canvas_h=1920):
    """Find the smoothed face position closest to `t_seconds`.

    Returns (origin_x, origin_y, confidence) where origin_x/origin_y are
    normalized to the canonical 1080x1920 canvas with rule-of-thirds
    adjustment (eyes sit ~10% of canvas height above face center, so the
    zoom origin lands on the eyes — that's the perceptual focal point on
    a face). Returns (None, None, 0.0) if no detection nearby or the
    closest detection failed (found=False).

    Smoothed trajectory is dense (one keyframe every ~3s); nearest-
    neighbor lookup is enough — the smoothing pass already made cx/cy
    continuous between samples.
    """
    if not trajectory:
        return None, None, 0.0
    closest = min(trajectory, key=lambda p: abs(float(p.get("t", 0.0)) - float(t_seconds)))
    if not closest.get("found"):
        return None, None, 0.0
    cx = float(closest.get("cx", 0))
    cy = float(closest.get("cy", 0))
    conf = float(closest.get("confidence", 0))
    # Normalize + rule-of-thirds eye offset. Face center ≈ nose; eyes sit
    # roughly 10% of canvas height above center for a typical talking-head
    # framing. Subtracting 0.1 in normalized space lands the zoom origin
    # on the eyes — the natural focal point. Clamp to [0, 1] in case the
    # face lies outside the canonical canvas (non-9:16 source where the
    # detection coords may overshoot the post-crop frame).
    origin_x = max(0.0, min(1.0, cx / float(canvas_w)))
    origin_y = max(0.0, min(1.0, cy / float(canvas_h) - 0.1))
    return origin_x, origin_y, conf


def _resolve_zoom_origin(ev, source_time_s, face_trajectory):
    """Resolve the zoom origin for a single ABE event.

    Contract (matches handler.py:~2980 in the system prompt):
      - If Gemini emitted originX/originY explicitly, use them verbatim.
        This is the non-face-element path (prop, gesture, whiteboard) —
        Gemini watched the proxy and chose coords on a thing the pipeline
        cannot detect.
      - Otherwise (the default face-zoom path), look up the nearest
        smoothed face detection to `source_time_s` and lock the origin
        onto the face's eye line via `_face_position_at`. Reuses the
        existing sparse trajectory; no new sampling.
      - When the trajectory has no `found=True` detection nearby, fall
        back to canvas center (0.5, 0.5) AND emit a `[divergence]
        component=zoom_origin` line so the gap is visible instead of
        silently drifting off-subject.

    Returns (origin_x, origin_y, was_resolved_by_face_lock: bool).
    """
    _gemini_x = ev.get("originX")
    _gemini_y = ev.get("originY")
    if _gemini_x is not None and _gemini_y is not None:
        return float(_gemini_x), float(_gemini_y), False

    _ox, _oy, _conf = _face_position_at(face_trajectory, source_time_s)
    if _ox is not None and _oy is not None:
        return round(_ox, 4), round(_oy, 4), True

    # No face box near this frame on a face-zoom event — log + center.
    # The prompt promised Gemini face-locking; the trajectory failed to
    # produce one. Either face detection found no face at that moment
    # (genuine — speaker turned, occlusion) or the sparse keyframes are
    # too sparse for this particular event. Either way, viewer-visible
    # if we just stay silent.
    _record_divergence(
        "zoom_origin",
        {
            "source_time_s": round(float(source_time_s), 3),
            "event_startMs": ev.get("startMs"),
            "expected": "face",
        },
        "fallback_to_center",
        final={"originX": 0.5, "originY": 0.5},
        reason="no_face_box_at_frame",
    )
    return 0.5, 0.5, False


def calculate_reframe_crop(face_positions, source_w, source_h, target_w=1080, target_h=1920):
    """
    Calculate a crop window that keeps the detected face near frame center.
    Returns crop positions in source-pixel coordinates, or None if no crop shift is needed.
    """
    if source_w == target_w and source_h == target_h:
        return None

    target_aspect = target_w / target_h
    source_aspect = source_w / source_h if source_h else target_aspect

    if source_aspect > target_aspect:
        crop_h = source_h
        crop_w = int(source_h * target_aspect)
    else:
        crop_w = source_w
        crop_h = int(source_w / target_aspect) if target_aspect else source_h

    crops = []
    for pos in face_positions:
        crop_x = int(pos["cx"] - crop_w // 2)
        crop_y = int(pos["cy"] - crop_h // 2)
        crop_x = max(0, min(crop_x, max(0, source_w - crop_w)))
        crop_y = max(0, min(crop_y, max(0, source_h - crop_h)))
        crops.append({
            "t": pos["t"],
            "crop_x": crop_x,
            "crop_y": crop_y,
            "crop_w": crop_w,
            "crop_h": crop_h,
            "found": bool(pos.get("found")),
        })

    return crops

_PRODUCER_STAMP_FIELDS = ("name", "version", "model", "measured_at")


def _analysis_is_stamped(a):
    """PRODUCER STAMP (Zac backend rider 2026-07-11): a real analysis blob
    carries producer:{name, version, model, measured_at} — POSITIVE identity.
    A stamped blob is a measurement by attestation; the frozen-corpus echo
    signature (_is_plan_echo_analysis) is the fallback for UNSTAMPED legacy
    blobs only. The stamp is a NEW top-level key and is additive-safe: the
    echo signature matches a canned compound of OTHER keys (audio/speech/
    shots/metadata), so adding `producer` never changes a match either way
    (gate-pinned)."""
    if not isinstance(a, dict):
        return False
    _p = a.get("producer")
    return isinstance(_p, dict) and all(_p.get(_k) for _k in _PRODUCER_STAMP_FIELDS)


def _worker_producer_stamp():
    """The worker's producer identity for any analysis blob it OWNS. Same
    schema as the frontend's stamp so every blob in the system carries
    positive provenance. measured_at is epoch seconds (Date-free)."""
    return {"name": "promptly-gpu-worker",
            "version": HANDLER_VERSION,
            "model": GEMINI_EDITORIAL_MODEL,
            "measured_at": time.time()}


def _is_plan_echo_analysis(a):
    """POISONED WELL (Zac rider 2026-07-11): historical result.analysis_data
    rows persisted the PLAN-DERIVED echo (the overwrite, killed 2eb7196) —
    a re-edit replaying one reopens the laundering loop from storage. This
    is the echo's CANNED COMPOUND SIGNATURE from
    build_analysis_from_gemini_recipe — matched whole, so a real analysis
    (an external producer with actual speech/shots/audio content) can
    never trip it. NOTE (fingerprint correction, reported): frame_layout
    presence does NOT discriminate — the echo structurally carries an
    all-defaults frame_layout; the canned tuple below is the honest test.
    Convicted in production: 8004e7e6's stored analysis_data matches this
    signature exactly (single 'Full video' shot + has_speech False on a
    talking video)."""
    try:
        if not isinstance(a, dict):
            return False
        _sp = a.get("speech") or {}
        _sh = a.get("shots") or []
        return (a.get("audio") == {"speech_source": "none"}
                and _sp.get("has_speech") is False
                and (_sp.get("segments") or []) == []
                and len(_sh) == 1
                and str(_sh[0].get("description") or "") == "Full video"
                and (a.get("metadata") or {}) == {})
    except Exception:
        return False


def normalize_analysis(parsed):
    if not parsed.get("speech"):
        parsed["speech"] = {"has_speech": False, "segments": [], "sentence_boundaries": []}
    if not parsed.get("safe_cut_points"):
        parsed["safe_cut_points"] = []
    if not parsed.get("peak_moments"):
        parsed["peak_moments"] = []
    if not parsed.get("highlights"):
        parsed["highlights"] = []
    if parsed.get("footage_assessment") and not parsed.get("video_profile"):
        parsed["video_profile"] = parsed["footage_assessment"]

    duration = float(parsed.get("duration") or 0)
    shots_raw = parsed.get("shots") or []
    shots = []
    for i, s in enumerate(shots_raw):
        shots.append({
            "start":         float(s.get("start") or 0),
            "end":           float(s.get("end") or duration),
            "visual":        s.get("visual") or "",
            "action":        s.get("action") or "",
            "energy":        float(s.get("energy") or 0.5),
            "editing_value": s.get("editing_value") or "",
            "delivery":      s.get("delivery") or "none",
            "description":   s.get("action") or s.get("visual") or f"Shot {i+1}",
            "score":         float(s.get("energy") or 0.5),
        })
    if not shots:
        shots = [{"start": 0, "end": duration, "description": "Full video", "score": 0.5,
                  "visual": "", "action": "", "energy": 0.5, "editing_value": "", "delivery": "none"}]

    raw_cb = parsed.get("color_baseline") or {}
    color_baseline = {
        "assessment":        raw_cb.get("assessment") or "",
        "brightness":        float(raw_cb["brightness"]) if isinstance(raw_cb.get("brightness"), (int, float)) else 1,
        "contrast":          float(raw_cb["contrast"]) if isinstance(raw_cb.get("contrast"), (int, float)) else 1,
        "saturation":        float(raw_cb["saturation"]) if isinstance(raw_cb.get("saturation"), (int, float)) else 1,
        "gamma":             float(raw_cb["gamma"]) if isinstance(raw_cb.get("gamma"), (int, float)) else 1,
        "color_temperature": raw_cb.get("color_temperature") if raw_cb.get("color_temperature") in ["warm", "cool", "neutral"] else "neutral",
    }
    raw_fl = parsed.get("frame_layout") or {}
    frame_layout = {
        "subject_position": raw_fl.get("subject_position") or "unknown",
        "existing_overlays": {
            "has_burned_captions": bool((raw_fl.get("existing_overlays") or {}).get("has_burned_captions")),
            "has_text_graphics":   bool((raw_fl.get("existing_overlays") or {}).get("has_text_graphics")),
            "overlay_locations":   (raw_fl.get("existing_overlays") or {}).get("overlay_locations") or "none detected",
        },
        "free_zones": raw_fl.get("free_zones") or "unknown",
    }

    # Hook, pacing, recommended_duration (new fields — backward compatible)
    raw_fa  = parsed.get("footage_assessment") or parsed.get("video_profile") or {}
    raw_hook = raw_fa.get("hook") or {}
    hook = {
        "timestamp":   float(raw_hook["timestamp"]) if isinstance(raw_hook.get("timestamp"), (int, float)) else 0.0,
        "description": str(raw_hook.get("description") or ""),
        "why":         str(raw_hook.get("why") or ""),
        "quality":     float(raw_hook["quality"]) if isinstance(raw_hook.get("quality"), (int, float)) else 0.5,
    } if raw_hook else None

    recommended_duration = None
    if isinstance(raw_fa.get("recommended_duration"), (int, float)):
        recommended_duration = int(raw_fa["recommended_duration"])

    pacing = str(raw_fa.get("pacing") or "").strip().lower()
    if pacing not in ("fast", "medium", "slow"):
        pacing = None

    raw_fq = parsed.get("footage_quality") or {}
    valid_noise       = {"none", "low", "medium", "high"}
    valid_sharpness   = {"soft", "normal", "sharp"}
    valid_highlight   = {"clipped", "bright", "normal", "dark"}
    valid_shadow      = {"crushed", "deep", "normal", "lifted"}
    valid_richness    = {"flat", "muted", "normal", "vivid"}
    valid_lighting    = {"natural_outdoor", "natural_indoor", "studio", "mixed", "unknown"}
    footage_quality = {
        "noise_level":       raw_fq.get("noise_level", "low") if raw_fq.get("noise_level") in valid_noise else "low",
        "source_sharpness":  raw_fq.get("source_sharpness", "normal") if raw_fq.get("source_sharpness") in valid_sharpness else "normal",
        "highlight_condition": raw_fq.get("highlight_condition", "normal") if raw_fq.get("highlight_condition") in valid_highlight else "normal",
        "shadow_condition":  raw_fq.get("shadow_condition", "normal") if raw_fq.get("shadow_condition") in valid_shadow else "normal",
        "color_richness":    raw_fq.get("color_richness", "normal") if raw_fq.get("color_richness") in valid_richness else "normal",
        "skin_tones_present": bool(raw_fq.get("skin_tones_present", True)),
        "lighting_type":     raw_fq.get("lighting_type", "unknown") if raw_fq.get("lighting_type") in valid_lighting else "unknown",
    }
    safe_cut_points = parsed.get("cut_points") or parsed.get("safe_cut_points") or []
    peak_moments = parsed.get("highlights") or parsed.get("peak_moments") or []
    vp = parsed.get("video_profile") or parsed.get("footage_assessment") or {}

    return {
        "duration":             duration,
        "shots":                shots,
        "speech":               parsed.get("speech") or {"has_speech": False, "segments": [], "sentence_boundaries": []},
        "audio":                parsed.get("audio") or {},
        "safe_cut_points":      safe_cut_points,
        "peak_moments":         peak_moments,
        "video_profile":        vp,
        "frame_layout":         frame_layout,
        "color_baseline":       color_baseline,
        "footage_quality":      footage_quality,
        "metadata":             parsed.get("metadata") or {},
        "visual_cuts":          [],
        "hook":                 hook,
        "recommended_duration": recommended_duration,
        "pacing":               pacing,
    }




# ─── BEAT DETECTION ──────────────────────────────────────────────────────────

def cluster_shot_changes(shot_changes, min_gap=0.5):
    """Filter ffmpeg scdet noise by collapsing detections within `min_gap`
    seconds into a single event (kept: the earliest). scdet at threshold=0.30
    fires on motion + lighting changes too, producing hundreds of detections
    on a fast-cut promo video; this clusters them to real visual cuts.
    """
    if not shot_changes:
        return []
    sorted_shots = sorted(shot_changes)
    clustered = [sorted_shots[0]]
    for _s in sorted_shots[1:]:
        if _s - clustered[-1] >= min_gap:
            clustered.append(_s)
    return clustered


def shot_change_word_boundaries(shot_changes, kept_words, snap_tolerance=0.60, shot_scores=None, out_scores=None):
    """Map each clustered shot change to a kept-word boundary (in kept-word
    index space) and its corresponding split-time (source seconds).

    For each shot change, find the kept-word EDGE (end of word N OR start
    of word N+1) closest within `snap_tolerance` seconds. The chosen
    boundary becomes the after-word-index N (last word of pre-split clip);
    the split time is word N's `.end` in source-time.

    Snap tolerance bumped from 0.30s → 0.60s — production sweep showed
    real cuts at score 12.60 and 12.07 silently dropped because the
    speaker was mid-sentence at the cut and the nearest word END was
    >0.30s away (even though the next word's START was <0.05s away).
    0.60s covers the longest English word at slow expressive tempo;
    also-check-the-next-word-start covers the mid-sentence case.

    When a detection can't be snapped after both expansions, _record_divergence
    logs it instead of dropping silently — that is the audit fix for
    the "FLAGGED cuts vanishing" bug.

    Returns a list of (new_idx, source_time_seconds) tuples, sorted by
    new_idx, deduplicated. Used by both:
      - the pre-Gemini CUT BOUNDARIES signal (uses new_idx values)
      - the post-Gemini clip splitter (uses source_time_seconds values)
    """
    if not shot_changes or not kept_words:
        return []
    clustered = cluster_shot_changes(shot_changes)
    seen_indices = set()
    out = []
    for _sc in clustered:
        _best_idx = None
        _best_dist = snap_tolerance
        _best_we = None
        for _new_idx, _w in enumerate(kept_words):
            _we = float(_w.get("end") or 0)
            # Distance to end of this word.
            _dist_end = abs(_we - _sc)
            if _dist_end <= _best_dist:
                _best_dist = _dist_end
                _best_idx = _new_idx
                _best_we = _we
            # Also check distance to start of the NEXT word — covers
            # mid-sentence cuts where the speaker resumes from a different
            # word and the cut lands inside the word-gap. The pre-split
            # boundary is still word N (the LAST kept word before the cut).
            if _new_idx + 1 < len(kept_words):
                _next_ws = float(kept_words[_new_idx + 1].get("start") or 0)
                _dist_start = abs(_next_ws - _sc)
                if _dist_start <= _best_dist:
                    _best_dist = _dist_start
                    _best_idx = _new_idx
                    _best_we = _we
        if (
            _best_idx is not None
            and 0 <= _best_idx < len(kept_words) - 1  # not the last word
            and _best_idx not in seen_indices
        ):
            out.append((_best_idx, _best_we))
            seen_indices.add(_best_idx)
            # Carry the scdet confidence score for this boundary out via the
            # side-channel dict (keyed by kept-word index). `_sc` is the
            # clustered detection time; shot_scores is keyed by round(t, 3).
            # Used only by the scene-change floor's confidence gate.
            if out_scores is not None and shot_scores is not None:
                out_scores[_best_idx] = shot_scores.get(round(float(_sc), 3))
        else:
            # Detection didn't snap. Could not place a boundary — log so
            # the silent drop becomes visible. The pre-Gemini boundary
            # union loses this cut, but at least we know.
            _reason = (
                "no_kept_word_edge_within_tolerance"
                if _best_idx is None
                else ("last_word_boundary" if _best_idx == len(kept_words) - 1
                      else "duplicate_after_clustering")
            )
            _record_divergence(
                "shot_change_snap",
                {
                    "source_time_s": round(float(_sc), 3),
                    "snap_tolerance_s": snap_tolerance,
                    "best_kept_word_idx": _best_idx,
                    "best_distance_s": (
                        round(float(_best_dist), 3) if _best_idx is not None else None
                    ),
                },
                "drop_unsnapped",
                reason=_reason,
            )
    out.sort(key=lambda t: t[0])
    return out


def _parse_scdet_output(stdout, stderr):
    """Parse scdet's metadata output → list of (timestamp_s, score) tuples,
    sorted by timestamp, deduplicated.

    scdet at sc_pass=1 emits per-frame metadata blocks to stdout like:
        frame:123 pts:41000 pts_time:1.366
        lavfi.scdet.mafd=...
        lavfi.scdet.score=0.412

    Some ffmpeg builds emit `lavfi.scd.score=` (older name) or send the
    info to stderr only. Both fallbacks are handled here.

    When the timestamp is parseable but the score isn't, the score is
    returned as 0.0 — the caller can filter it out if it cares about
    score-based filtering.
    """
    detections = []
    _pending_t = None
    for _line in (stdout or "").splitlines():
        _line = _line.strip()
        if _line.startswith("frame:") and "pts_time:" in _line:
            _tok = _line.split("pts_time:")[-1].split()[0]
            try:
                _pending_t = float(_tok)
            except ValueError:
                _pending_t = None
        elif "lavfi.scdet.score=" in _line or "lavfi.scd.score=" in _line:
            _stok = _line.split("score=")[-1].strip()
            try:
                _score = float(_stok)
            except ValueError:
                _score = 0.0
            if _pending_t is not None:
                detections.append((round(_pending_t, 3), round(_score, 3)))
                _pending_t = None
    # Stderr fallback for builds that send metadata there without the
    # per-frame stdout block. scdet logs flagged frames like:
    #   [Parsed_scdet_0 @ 0x...] lavfi.scdet.score:3.12 pts_time:5.482
    if not detections and stderr:
        for _line in stderr.splitlines():
            if "Parsed_scdet" not in _line or "pts_time:" not in _line:
                continue
            _ttok = _line.split("pts_time:")[-1].split()[0]
            try:
                _t = float(_ttok)
            except ValueError:
                continue
            _score = 0.0
            if "score:" in _line:
                _stok = _line.split("score:")[-1].split()[0]
                try:
                    _score = float(_stok)
                except ValueError:
                    pass
            detections.append((round(_t, 3), round(_score, 3)))
    # De-duplicate by timestamp, keep first observed score.
    seen = set()
    out = []
    for _t, _s in detections:
        if _t in seen:
            continue
        seen.add(_t)
        out.append((_t, _s))
    out.sort(key=lambda ts: ts[0])
    return out


# scdet runs at this wide-net threshold so EVERY potential cut surfaces
# (down to mild motion). Python then filters to the production threshold
# (default 12.0) for the return value, AND logs every parsed detection
# under `[scdet-sweep]` so a single grep tells the operator what scores
# the source actually produced. Load-bearing for diagnosing same-framing
# splices that live below threshold=12 — the "I expect" → "I know"
# conversion. Set to 1.0 to capture the typical same-framing splice
# zone (~1.5-6) without flooding pure-noise frames at 0.x.
_SCDET_SWEEP_THRESHOLD = 1.0


def detect_shot_changes(source_path, threshold=7.0, out_scores=None):
    """Detect hard shot changes in the source video via ffmpeg's `scdet`
    (scene change detect) filter.

    `threshold` is scdet's scene-score threshold on a 0-100 scale
    (ffmpeg's vf_scdet.c sets default=10, range 0-100). Previously we
    passed 0.30 thinking it was a 0-1 sensitivity dial — that produced
    300+ detections on a 22s video (every frame with any motion at all).
    Then 12.0 — which filtered motion noise but ALSO filtered real cuts
    on normal-framing footage that scored 8-11.

    Lowered to 7.0 based on production sweep data showing real cuts on
    normal-framing footage at 8.72-10.23 (well above motion floor 1-3)
    with a ~5.7 gap between motion ceiling and cut floor. Threshold 7.0
    sits in that gap. Caveat: footage with extreme gestures may produce
    motion scores 8-9 (false positives). The [scdet-sweep] log shows
    every detection with its score so false-positive surface stays
    visible across renders — escalate to adaptive thresholding if FPs
    become frequent.

    SEPARATELY: same-framing same-spot splices score ~2-6 because the
    visual delta between back-to-back takes is near zero — below ANY
    threshold the noise floor allows. Those need an audio-discontinuity
    detector, not threshold tuning. See the sweep log to confirm the
    score distribution on this source.

    To diagnose that miss rate without guessing, scdet runs internally
    at _SCDET_SWEEP_THRESHOLD (much lower) and every parsed detection
    is logged with its score under `[scdet-sweep]`. The RETURN value
    is filtered to >= `threshold` so production behavior is unchanged;
    the sweep is purely observational. After a render, grep
    `[scdet-sweep]` and check whether the user's known cut timestamps
    appear as low-score detections — if so, the visual signal exists
    but the threshold is filtering it; if not, the visual signal genuinely
    isn't there and the cut needs a different detector (e.g. audio
    discontinuity).
    """
    cmd = [
        "ffmpeg", "-i", source_path, "-an",
        "-vf", f"scdet=threshold={_SCDET_SWEEP_THRESHOLD}:sc_pass=1,metadata=print:file=-",
        "-f", "null", "-",
    ]
    proc = subprocess.run(cmd, capture_output=True, text=True, timeout=60)
    detections = _parse_scdet_output(proc.stdout, proc.stderr)

    # Sweep log — one grep-stable line per detection. Score-tagged so we
    # can see the distribution and decide whether a threshold sweep would
    # have caught the missed cuts, or whether they live below the noise
    # floor entirely.
    for _t, _score in detections:
        _flag = "FLAGGED" if _score >= threshold else "below"
        print(
            f"[scdet-sweep] t={_t:.3f}s score={_score:.2f} "
            f"({_flag} @ threshold={threshold:.1f})",
            flush=True,
        )

    # Production return: timestamps whose score crossed the production
    # threshold. If score parsing failed across the board (score=0.0 for
    # every entry — older ffmpeg builds), fall back to the legacy behavior
    # of trusting scdet's own threshold filter by running ONCE more at the
    # production threshold instead. This is the no-regression guard.
    _scored = [(t, s) for t, s in detections if s > 0.0]
    if not _scored and detections:
        # Parser couldn't recover scores; re-run scdet at the production
        # threshold (the original 2025 behavior) and take its filtered set.
        print(
            f"[shot-changes] WARNING: scdet output had no parsable scores — "
            f"falling back to legacy single-call threshold filter "
            f"(detections={len(detections)}, all score=0.0)",
            flush=True,
        )
        cmd_legacy = [
            "ffmpeg", "-i", source_path, "-an",
            "-vf", f"scdet=threshold={threshold}:sc_pass=1,metadata=print:file=-",
            "-f", "null", "-",
        ]
        proc_legacy = subprocess.run(cmd_legacy, capture_output=True, text=True, timeout=60)
        legacy_detections = _parse_scdet_output(proc_legacy.stdout, proc_legacy.stderr)
        changes = sorted({t for t, _ in legacy_detections})
        # Legacy path recovered no usable scores → leave out_scores empty so
        # the scene-change floor fails OPEN (decorates) rather than skipping.
    else:
        changes = sorted({t for t, s in detections if s >= threshold})
        if out_scores is not None:
            # Map flagged timestamp → score so the scene-change floor can gate
            # its automatic backfill on confidence. Keyed by round(t, 3) to
            # match the boundary snapper's lookup; keeps the MAX per timestamp.
            for _t, _s in detections:
                if _s >= threshold:
                    _k = round(float(_t), 3)
                    if _s > out_scores.get(_k, 0.0):
                        out_scores[_k] = float(_s)

    print(
        f"[shot-changes] Detected {len(changes)} cuts "
        f"(threshold={threshold}, sweep_window>={_SCDET_SWEEP_THRESHOLD})",
        flush=True,
    )
    return changes


# ─── DEEPGRAM TRANSCRIPTION ───────────────────────────────────────────────────


def prepare_audio_for_deepgram(source_path: str) -> bytes:
    """Extract bit-perfect mono FLAC for transcription.

    Hand Deepgram the highest-fidelity audio we can: raw PCM (sample-rate +
    channel normalized) wrapped in lossless FLAC. No level processing, no
    EQ, no compression — every dB and every transient reaches the model
    exactly as it sat in the source's PCM-decoded audio.

      • mono channel — Deepgram's models are tuned for mono speech
      • 48 kHz sample rate — preserves all source detail
      • lossless FLAC encode — no second-generation lossy compression on top
        of whatever the source already lost in its AAC encode

    Single-pass loudnorm was previously applied here to "boost confidence on
    soft consonants" but ffmpeg's single-pass loudnorm is a dynamic-range
    compressor that smears word onsets — confirmed source of substitution
    errors like "for Israel" → "phraise room". Nova-3 doesn't need our help
    on levels; it was trained on raw phone calls and varied-level podcasts.

    Returns FLAC bytes ready for Deepgram's transcribe_file. Typical size on
    a 60s clip: ~5-8 MB (vs 80 MB for the full video), so the upload is
    actually faster than sending the raw file too.
    """
    cmd = [
        "ffmpeg", "-v", "error", "-threads", "0",
        "-i", source_path,
        "-vn", "-ac", "1", "-ar", "48000",
        "-c:a", "flac", "-compression_level", "5",
        "-f", "flac", "-",
    ]
    proc = subprocess.run(cmd, capture_output=True, timeout=120)
    if proc.returncode != 0:
        raise RuntimeError(
            f"Deepgram audio prep failed: {(proc.stderr or b'').decode('utf-8', errors='replace')[-300:]}"
        )
    print(
        f"[deepgram-prep] Extracted {len(proc.stdout) / 1024:.0f}KB FLAC "
        f"(mono 48kHz, lossless — no level processing)",
        flush=True,
    )
    return proc.stdout


def _deepgram_options(keywords=None, language="multi"):
    """Deepgram Nova-3 transcription options.

    `keywords` is an optional list of `"term:intensifier"` strings that
    boost recognition for proper nouns (names, places, brand terms) the
    speaker is likely to use. Without these, Nova-3 mishears uncommon
    proper nouns (e.g. "Ryan" → "right").

    Nova-3 uses `keyterm` (Nova-2 used `keywords`). Sending `keywords`
    against Nova-3 fails the request with HTTP 400: "Keywords are not
    supported for Nova-3. Please use `keyterm` instead." Nova-3 also
    doesn't accept the `term:intensifier` suffix — it handles boosting
    internally — so we strip the legacy `:N` form before sending.
    """
    kwargs = dict(
        # LATIN-SCOPE FLIP (2026-07-17): language=multi (was detect_language=True).
        # detect_language returned 0 words + a wrong language label on ~40% of
        # non-English talking videos (measured) — a false NO_SPEECH. multi
        # reliably transcribes them. A downstream SCRIPT-COVERAGE gate then only
        # lets scripts the caption fonts actually render (Latin today) reach the
        # render path; uncovered scripts take the honest language-named reject.
        # Verified 2026-07-17: multi accepts the full option set below incl.
        # keyterm (HTTP 200, no PAYLOAD_ERROR). `language` is overridable for the
        # Arabic-bridge route (language="ar" → native Arabic script vs multi's
        # romanization); default "multi" keeps the main path byte-identical.
        model="nova-3", language=language,
        smart_format=True, utterances=True, punctuate=True, diarize=True,
        # Deepgram silently strips disfluencies ("um", "uh", "uhm") from the
        # transcript by default. For editorial cutting we need those tokens
        # in the word list — the mechanical filler detector relies on seeing
        # the actual hesitations to remove them. Turning this on means the
        # ASR returns "um" / "uh" / "uhm" with timestamps just like any other
        # word.
        filler_words=True,
    )
    if keywords:
        _terms = []
        for k in keywords:
            term = str(k).split(":", 1)[0].strip()
            if term:
                _terms.append(term)
        if _terms:
            kwargs["keyterm"] = _terms
    return PrerecordedOptions(**kwargs)


def _extract_proper_noun_keywords(text):
    """Pull Title-Case proper nouns from a free-text input (the user's
    vibe / title / caption) for Deepgram keyword boosting.

    Heuristic: Title-Case tokens that aren't common sentence-start words.
    "Interview with Ryan about Hatikvah" → ["Ryan:5", "Hatikvah:5"].
    "Viral engaging video" → [] (no proper nouns).

    Returns a list of `"term:5"` strings ready to pass to Deepgram.
    """
    if not text:
        return []
    # Common Title-Case words that aren't proper nouns (sentence starts,
    # generic capitalization). Filter these out to avoid noise.
    _COMMON_TITLECASE = frozenset({
        "I", "The", "A", "An", "And", "Or", "But", "So", "If", "When",
        "What", "Why", "How", "Where", "Who", "This", "That", "These", "Those",
        "My", "Your", "His", "Her", "Our", "Their", "Its",
        "Is", "Are", "Was", "Were", "Be", "Been", "Being",
        "Viral", "Engaging", "Video", "Edit", "Edits", "Editing", "Clip",
        "Short", "Shorts", "Reel", "Reels", "TikTok",
    })
    out = []
    seen = set()
    for tok in str(text).split():
        # Strip surrounding punctuation, keep the lemma.
        clean = "".join(ch for ch in tok if ch.isalpha() or ch == "-")
        if not clean or len(clean) < 2:
            continue
        if not clean[0].isupper():
            continue
        if clean in _COMMON_TITLECASE:
            continue
        if clean.lower() in seen:
            continue
        seen.add(clean.lower())
        out.append(f"{clean}:5")
    return out



def _parse_deepgram_response(resp):
    """Common response parsing for both file-based and URL-based Deepgram calls."""
    alt = resp.results.channels[0].alternatives[0]
    raw_words = alt.words or []
    words = [
        {
            "word":            w.word,
            "punctuated_word": getattr(w, "punctuated_word", w.word),
            "start":           float(w.start if w.start is not None else 0.0),
            "end":             float(w.end if w.end is not None else 0.0),
            "confidence":      float(getattr(w, "confidence", 1.0) or 1.0),
            # speaker is None (not absent) when diarize is off — e.g. the
            # Arabic-bridge language=ar probe. int(None) would crash the parse;
            # `or 0` makes it robust so the probe (and any no-diarize call) works.
            "speaker":         int(getattr(w, "speaker", 0) or 0),
            # per-word language tag (language=multi populates it) — feeds the
            # Arabic-confusion signature (_looks_confused): multi tags romanized
            # Arabic incoherently (e.g. a fr/hi mix on Latin text). Additive.
            "language":        getattr(w, "language", None),
        }
        for w in raw_words
    ]

    # Utterances group words by speaker turn and are more reliable than
    # per-word speaker labels. Override per-word labels with utterance-level
    # speaker assignments when available. Also capture the utterance list
    # for downstream consumers that need explicit turn boundaries.
    raw_utterances = getattr(resp.results, "utterances", None) or []
    utterances = []
    if raw_utterances:
        for utt in raw_utterances:
            utt_start = float(getattr(utt, "start", 0))
            utt_end = float(getattr(utt, "end", 0))
            utt_speaker = int(getattr(utt, "speaker", 0))
            utterances.append({
                "start": utt_start,
                "end": utt_end,
                "speaker": utt_speaker,
            })
            for w in words:
                if w["start"] >= utt_start - 0.05 and w["end"] <= utt_end + 0.05:
                    w["speaker"] = utt_speaker
        print(f"[deepgram] Applied {len(utterances)} utterance-level speaker labels", flush=True)

    speaker_ids = set(w["speaker"] for w in words)
    if len(speaker_ids) > 1:
        print(f"[deepgram] Detected {len(speaker_ids)} speakers", flush=True)

    # Surface the language multi detected (per-channel), for the script-coverage
    # gate's honest, language-named rejection. Best-effort — never a hard field.
    _detected_lang = None
    try:
        _ch0 = resp.results.channels[0]
        _detected_lang = getattr(_ch0, "detected_language", None)
        if not _detected_lang:
            _langs = getattr(_ch0, "languages", None) or []
            _detected_lang = _langs[0] if _langs else None
    except Exception:
        _detected_lang = None

    print(f"[deepgram] Transcribed {len(words)} words (lang={_detected_lang})", flush=True)
    return {"text": alt.transcript or "", "words": words, "utterances": utterances,
            "detected_language": _detected_lang}


def _deepgram_is_retriable_error(msg):
    """Classify a Deepgram error message as retriable (rate limits, 5xx, network)."""
    m = str(msg)
    return (
        "429" in m or "rate" in m.lower() or
        "500" in m or "502" in m or "503" in m or "504" in m or
        "timeout" in m.lower() or "connection" in m.lower() or
        "temporarily" in m.lower()
    )


def transcribe_audio(source_path, keywords=None, language="multi"):
    """File-based Deepgram with loudness-normalized FLAC audio prep.

    Sends the cleaned mono 48 kHz FLAC produced by prepare_audio_for_deepgram
    rather than the raw video bytes — gives the model uniform-level audio
    and saves bandwidth (FLAC of just the audio stream is much smaller than
    the full video). 3-attempt exponential backoff on retriable errors.

    `keywords` (optional): list of `"term:intensifier"` strings for proper-
    noun boosting. Default None = no boosting. Pass keywords extracted
    from the user's vibe/title to bias Deepgram toward likely names.
    """
    if DeepgramClient is None or PrerecordedOptions is None:
        print("[pipeline] transcription skipped: deepgram not available", flush=True)
        return {"text": "", "words": []}
    dg = DeepgramClient(api_key=os.environ["DEEPGRAM_API_KEY"])
    audio_bytes = prepare_audio_for_deepgram(source_path)
    if keywords:
        _terms_for_log = [str(k).split(":", 1)[0].strip() for k in keywords]
        _terms_for_log = [t for t in _terms_for_log if t]
        print(
            f"[deepgram] Sending {len(audio_bytes) / 1024:.0f}KB FLAC audio "
            f"with {len(_terms_for_log)} keyterm boost(s): {_terms_for_log}",
            flush=True,
        )
    else:
        print(f"[deepgram] Sending {len(audio_bytes) / 1024:.0f}KB FLAC audio", flush=True)
    options = _deepgram_options(keywords=keywords, language=language)
    _t0 = time.time()
    last_err = None
    for attempt in range(3):
        try:
            resp = dg.listen.prerecorded.v("1").transcribe_file(
                {"buffer": audio_bytes, "mimetype": "audio/flac"},
                options,
            )
            result = _parse_deepgram_response(resp)
            print(f"[metric] stage_duration stage=transcribe_file duration_ms={int((time.time()-_t0)*1000)} attempt={attempt+1}", flush=True)
            return result
        except Exception as e:
            last_err = e
            if attempt < 2 and _deepgram_is_retriable_error(e):
                backoff = 2 ** attempt
                print(f"[deepgram] file attempt {attempt+1} retriable ({str(e)[:120]}) — retry in {backoff}s", flush=True)
                time.sleep(backoff)
                continue
            break
    raise RuntimeError(f"Deepgram transcription failed after 3 attempts: {last_err}") from last_err


def _detect_nonenglish_speech(source_path):
    """Interim non-English honesty (2026-07-17). When the main nova-3
    detect_language pass returns 0 words, re-check the SAME audio with
    language=multi — which reliably detects Hindi/Spanish/Russian/etc. speech
    that detect_language misses (measured: ~40% of NO_SPEECH rejections carry
    real non-English speech). Returns (language_code_or_None, word_count).

    Used ONLY to make the rejection TRUE ("we heard you — English-only for
    now"), NEVER to render: the pipeline stays English-only until the multi
    render test clears the global flip. Best-effort — any failure returns
    (None, 0) so the plain NO_SPEECH reject proceeds unchanged. Runs only on
    the reject path (0 words), so it adds a Deepgram call to rejections only,
    never to a normal edit."""
    try:
        if DeepgramClient is None or PrerecordedOptions is None:
            return (None, 0)
        dg = DeepgramClient(api_key=os.environ["DEEPGRAM_API_KEY"])
        audio_bytes = prepare_audio_for_deepgram(source_path)
        options = PrerecordedOptions(
            model="nova-3", language="multi", smart_format=True, punctuate=True)
        resp = dg.listen.prerecorded.v("1").transcribe_file(
            {"buffer": audio_bytes, "mimetype": "audio/flac"}, options)
        parsed = _parse_deepgram_response(resp)
        n = len(parsed.get("words") or [])
        lang = None
        try:
            _ch0 = resp.results.channels[0]
            lang = getattr(_ch0, "detected_language", None)
            if not lang:
                _langs = getattr(_ch0, "languages", None) or []
                lang = _langs[0] if _langs else None
        except Exception:
            lang = None
        print(f"[nonenglish-check] language=multi found {n} words (lang={lang})", flush=True)
        return (lang, n)
    except Exception as _e:
        print(f"[nonenglish-check] skipped ({type(_e).__name__}) — NO_SPEECH proceeds", flush=True)
        return (None, 0)


# ── SCRIPT-COVERAGE GATE (Latin-scope language flip, 2026-07-17) ──────────────
# language=multi transcribes every language, but the caption fonts can only
# render some scripts — rendering one they can't produces tofu boxes, which
# fails the zero-defect bar WORSE than an honest rejection. So a transcript may
# reach the render path ONLY if its dominant Unicode script is covered.
#
# _SCRIPT_COVERAGE is DERIVED FROM THE FONT INVENTORY, not hope: every designed
# caption family (src/remotion/src/captions/shared/fonts.ts — Montserrat, Inter,
# Poppins, DMSans, Teko, Playfair, Lora, …) loads the LATIN subset only, and the
# render image installs NO Indic font (modal_app.py: fonts-dejavu-core only).
# DejaVu's Cyrillic fallback is legible but OFF-DESIGN → excluded per the
# zero-defect bar. So covered today = Latin. validate_deploy gate-enforces that
# this set cannot drift ahead of the fonts (tofu stays unconstructible).
_SCRIPT_COVERAGE = frozenset({"Latin"})

# Workstream B (2026-07-19): the coverage MODEL flips from an allowlist (Latin
# only) to a DENYLIST of scripts PROVEN to render broken. A1/A2 installed Noto
# for every script in _SCRIPT_RANGES (fonts-noto-core + -extra + -cjk) and the
# contact sheet proved each shapes clean with correct direction (Arabic/Hebrew
# RTL, Devanagari conjuncts, Thai stacks, CJK, color emoji) — so the denylist is
# empty. Gated behind PROMPTLY_EDIT_IN_LANGUAGE (baked OFF) so enablement and the
# in-language editorial prompt move together: rendering non-Latin WITHOUT the
# in-language instruction would ship source-language captions under English MG
# chrome. Unset the flag → back to the Latin-only allowlist, no logic redeploy.
_SCRIPT_DENYLIST = frozenset({"Arabic"})  # DEFAULT denylist; env-overridable below
# Arabic RENDERS perfectly (A2 contact sheet: joining, lam-alef, RTL, fonts all
# proven) — but Deepgram nova-3 `language=multi` ROMANIZES Arabic audio to Latin
# transliteration instead of Arabic script (measured: cert run; Cyrillic/
# Devanagari/CJK all come through in native script, Arabic does not). Romanized
# captions are worse than an honest rejection, so Arabic takes the named reject
# ("Arabic support is coming") until the ar-route certification passes. The
# Arabic BRIDGE detects it; the ROUTE re-transcribes language=ar (built, inert).
# [[project_multilingual_initiative]]


def _script_denylist():
    """Scripts that may NOT reach render — ENV-OVERRIDABLE so graduation is an env
    flip with a one-line rollback forever (the PLAN_CAPTURE/EDIT_IN_LANGUAGE
    pattern), never a prod-behavior change before certification. Read at call time.
      • unset          → the _SCRIPT_DENYLIST default ({"Arabic"})
      • "" (empty)     → graduated: no script denied (Arabic routes to language=ar)
      • "Arabic,Foo"   → explicit set
    The Arabic cert sets PROMPTLY_SCRIPT_DENYLIST="" IN-PROCESS to exercise the
    route with zero production impact; graduation bakes it "" into the image env."""
    _raw = os.environ.get("PROMPTLY_SCRIPT_DENYLIST")
    if _raw is None:
        return _SCRIPT_DENYLIST
    return frozenset(s.strip() for s in _raw.split(",") if s.strip())


def _edit_in_language_enabled():
    """Whether the multilingual render path (denylist coverage + in-language
    editorial) is live. One flag so the two move together."""
    return bool(os.environ.get("PROMPTLY_EDIT_IN_LANGUAGE", "").strip())


def _burned_text_enabled():
    """Whether the burned-in-text guard is live — ONE flag gating the whole
    feature: the sharpened Stage-0 prompt block (belt), the deterministic EAST
    text detector that runs on the ORIGINAL source frames (guarantee), and the
    gates that feed its signal into caption suppression / MG-overlay redirects /
    the new zoom constraint. Default OFF → prompt is byte-identical, the detector
    never runs, and every burned-text value stays model-declared exactly as
    today. Flip held for Zac after the detector is cert'd on real +/- clips."""
    return bool(os.environ.get("PROMPTLY_BURNED_TEXT", "").strip())


def _script_reaches_render(script):
    """True if a dominant script may reach the render path. Under
    PROMPTLY_EDIT_IN_LANGUAGE it's the denylist model (every font-backed script
    except proven failures); otherwise the legacy Latin-only allowlist. Tofu
    stays unconstructible either way: an unlisted script classifies as its
    nearest listed range or falls through to Latin, and no listed script lacks a
    Noto font."""
    if _edit_in_language_enabled():
        return script not in _script_denylist()
    return script in _SCRIPT_COVERAGE

# Codepoint-range → script classifier (stdlib unicodedata exposes no Script
# property). Common chars (digits/punct/space/symbols) are script-neutral and
# never counted.
_SCRIPT_RANGES = (
    ("Latin", ((0x0041, 0x024F), (0x1E00, 0x1EFF), (0x2C60, 0x2C7F), (0xA720, 0xA7FF))),
    ("Cyrillic", ((0x0400, 0x052F), (0x2DE0, 0x2DFF), (0xA640, 0xA69F))),
    ("Devanagari", ((0x0900, 0x097F), (0xA8E0, 0xA8FF))),
    ("Bengali", ((0x0980, 0x09FF),)),
    ("Gurmukhi", ((0x0A00, 0x0A7F),)),
    ("Gujarati", ((0x0A80, 0x0AFF),)),
    ("Tamil", ((0x0B80, 0x0BFF),)),
    ("Telugu", ((0x0C00, 0x0C7F),)),
    ("Kannada", ((0x0C80, 0x0CFF),)),
    ("Malayalam", ((0x0D00, 0x0D7F),)),
    ("Arabic", ((0x0600, 0x06FF), (0x0750, 0x077F), (0x08A0, 0x08FF))),
    ("Hebrew", ((0x0590, 0x05FF),)),
    ("Thai", ((0x0E00, 0x0E7F),)),
    ("Han", ((0x3400, 0x4DBF), (0x4E00, 0x9FFF))),
    ("Hiragana", ((0x3040, 0x309F),)),
    ("Katakana", ((0x30A0, 0x30FF),)),
    ("Hangul", ((0x1100, 0x11FF), (0xAC00, 0xD7AF))),
    ("Greek", ((0x0370, 0x03FF),)),
)

# Fallback language hint per script when Deepgram returns no code.
_SCRIPT_LANG_HINT = {
    "Devanagari": "hi", "Cyrillic": "ru", "Arabic": "ar", "Hebrew": "he",
    "Han": "zh", "Hiragana": "ja", "Katakana": "ja", "Hangul": "ko",
    "Tamil": "ta", "Telugu": "te", "Bengali": "bn", "Gujarati": "gu",
    "Gurmukhi": "pa", "Malayalam": "ml", "Kannada": "kn", "Thai": "th", "Greek": "el",
}

# Human-readable language names for the in-language editorial prompt (Workstream
# B). Deepgram language=multi returns a code (sometimes region-tagged, "es-419");
# a name reads better to Gemini than a code. Covers the Tier-1 nine + the common
# multi languages; anything unmapped falls back to the script's canonical lang,
# then the bare code.
_LANG_DISPLAY_NAME = {
    "en": "English", "es": "Spanish", "pt": "Portuguese", "fr": "French",
    "de": "German", "it": "Italian", "nl": "Dutch", "hi": "Hindi",
    "ja": "Japanese", "ko": "Korean", "zh": "Chinese", "ru": "Russian",
    "ar": "Arabic", "id": "Indonesian", "tr": "Turkish", "pl": "Polish",
    "uk": "Ukrainian", "he": "Hebrew", "th": "Thai", "vi": "Vietnamese",
    "sv": "Swedish", "da": "Danish", "no": "Norwegian", "fi": "Finnish",
    "cs": "Czech", "ro": "Romanian", "hu": "Hungarian", "el": "Greek",
    "ta": "Tamil", "te": "Telugu", "bn": "Bengali", "gu": "Gujarati",
    "pa": "Punjabi", "ml": "Malayalam", "kn": "Kannada", "ur": "Urdu",
    "fa": "Persian", "ms": "Malay", "tl": "Tagalog",
}


def _source_language_name(detected_language, script):
    """Human-readable source language for the in-language editorial prompt.
    Prefers Deepgram's detected code (region tag stripped); falls back to the
    script's canonical language, then the script name itself. Never raises."""
    code = str(detected_language or "").strip().lower()
    base = code.split("-", 1)[0] if code else ""
    if base in _LANG_DISPLAY_NAME:
        return _LANG_DISPLAY_NAME[base]
    hint = _SCRIPT_LANG_HINT.get(script)
    if hint in _LANG_DISPLAY_NAME:
        return _LANG_DISPLAY_NAME[hint]
    return (str(script) if script and script != "Latin" else "the speaker's")


# Workstream C — verification tiers. Tier-1 = CERTIFIED: the contact sheet
# proved each script clean (Latin, Arabic RTL, Devanagari, CJK, Cyrillic) and
# these are the highest-traffic languages, so they render with full confidence.
# Tier-2 = every other font-backed language: enabled under the flag but WATCHED
# via language telemetry (below) rather than certified — a Tier-2 language that
# starts failing surfaces in the daily report instead of failing silently.
_TIER1_LANGUAGES = frozenset({
    "hi", "es", "pt", "ar", "fr", "de", "ru", "id", "ja",
})


def _language_tier(lang_code, script=None):
    """1 for a certified Tier-1 language, 2 for any other (enabled+watched).
    Falls back to the script's canonical language when no code is given."""
    base = str(lang_code or "").strip().lower().split("-", 1)[0]
    if not base:
        base = _SCRIPT_LANG_HINT.get(script, "")
    return 1 if base in _TIER1_LANGUAGES else 2


def _is_non_english(lang_code, script):
    """A render worth language-tagging: a non-English detected language, or a
    non-Latin script when the code is missing/ambiguous. English Latin renders
    (the overwhelming majority) are skipped so the telemetry stays signal."""
    base = str(lang_code or "").strip().lower().split("-", 1)[0]
    if base:
        return base != "en"
    return bool(script) and script != "Latin"


# ─── ARABIC BRIDGE (speculative dual-transcribe, 2026-07-20) ─────────────────
# Deepgram nova-3 `language=multi` ROMANIZES Arabic audio to Latin transliteration
# instead of Arabic script, and its language detector mislabels it (detected=None,
# per-word tags an incoherent fr/hi mix). So _dominant_script sees Latin and the
# Arabic denylist LEAKS — a real Arabic upload would render romanized garbage.
# The fix (Zac's ruling): detect Deepgram's own confusion SIGNATURE, then confirm
# with a cheap `language=ar` probe (nova-3 → perfect Arabic script, verified).
# Confirmed Arabic is treated AS Arabic → honest denylist reject today; the SAME
# detection routes it to the ar-transcript once Arabic graduates off the denylist.
# Zero new deps: the text-LID is a stopword check.

# Languages whose native script is NON-Latin — a Latin-script transcript tagged
# with one of these is the romanization tell.
_NONLATIN_LANG_CODES = frozenset({
    "ar", "hi", "ja", "zh", "ko", "ru", "he", "th", "fa", "ur", "bn", "ta",
    "te", "kn", "ml", "gu", "pa", "mr", "el", "uk", "sr", "bg", "am",
})

# Dependency-free text-LID by stopword DENSITY. Comprehensive ~30-word function-
# word sets per Latin language — real text of a language is 20-50% these words;
# romanized Arabic hits only a couple by CHANCE (short words like "a"/"da"/"na"),
# so its density stays ~10%. Absolute-hit counting was too crude (romanized
# Arabic coincidentally hit 2 Portuguese stopwords and got mis-placed); density
# is the reliable separator (measured: all 6 certified Latin langs 0.17-0.50,
# romanized Arabic 0.13). Below the threshold → unplaceable → the ar probe fires.
_LATIN_STOPWORDS = {
    "en": {"the","and","is","to","of","a","in","that","it","you","for","on","are","was","with","as","at","be","this","have","from","or","by","not","but","what","all","we","they","your","so","up","one","more","than"},
    "es": {"de","la","que","el","en","y","los","se","no","un","por","con","una","su","para","es","al","lo","como","más","pero","sus","le","ya","o","este","del","todo","esta","cuando","muy","sin"},
    "fr": {"de","la","le","et","les","des","un","une","est","que","dans","pour","qui","pas","sur","au","ce","il","plus","ne","se","son","mais","ou","avec","tout","nous","comme","je","vous"},
    "de": {"der","die","das","und","ist","ein","eine","nicht","mit","auf","für","den","dem","im","zu","sich","auch","es","an","wie","so","nur","bei","vor","wenn","sie","wir","ich","aber","noch","nach","aus","sind","hat","werden","kurz","alles"},
    "pt": {"de","que","e","o","a","do","da","em","um","para","com","não","uma","os","no","se","na","por","mais","as","dos","como","mas","ao","ele","das","seu","sua","ou","quando","muito","antes","pouco","tudo"},
    "it": {"di","che","e","la","il","un","per","con","non","una","è","le","in","da","del","al","lo","si","dei","come","più","ma","anche","o","se","gli","della"},
    "id": {"yang","dan","di","itu","dengan","untuk","tidak","ini","ada","dari","akan","pada","juga","saya","ke","karena","tak","sudah","saat","orang","lebih","atau","bisa","mereka"},
    "nl": {"de","en","het","van","een","is","dat","niet","op","te","zijn","met","voor","er","aan","die","ook","als","maar","om"},
    "tr": {"bir","ve","bu","için","ile","de","da","çok","ne","ben","o","ama","gibi","daha","her","en","kadar","sonra"},
    "pl": {"nie","to","się","na","jest","że","co","jak","do","w","z","o","tak","ale","po","tym","już","jego"},
}

_LATIN_LID_MIN_DENSITY = 0.15  # ≥ → confidently a known language (skip probe)

# Cyrillic function-word sets — Deepgram multi transliterates Arabic into
# CYRILLIC as well as Latin (measured: the same speaker romanized Latin one run,
# Cyrillic the next), so the confusion signature must read Cyrillic text too.
# Real Russian/Ukrainian/Bulgarian is dense in these; Cyrillic-transliterated
# Arabic ("мувами ин-насия стаслимуна кобиль…") hits almost none.
_CYRILLIC_STOPWORDS = {
    "ru": {"и","в","не","на","что","я","с","он","как","это","то","а","но","по","у","за","от","мы","вы","они","она","так","же","бы","из","к","о","все","всё","его","её","их","был","была","было","только","когда","уже","для","до","или","если","чтобы","есть","нет","при","вот","чем","перед","прямо","люди","людей"},
    "uk": {"і","в","не","на","що","я","з","він","як","це","то","а","але","по","у","за","від","ми","ви","вони","вона","так","же","б","із","до","о","всі","його","її","їх","був","була","було","тільки","коли","вже","для","або","якщо","щоб","є"},
    "bg": {"и","в","не","на","що","аз","с","той","как","това","то","а","но","по","у","за","от","ние","вие","те","тя","така","до","о","все","него","нея","тях","беше","само","когато","вече","или","ако","да","е","се","ще","който"},
}


def _stopword_lid(text, tables):
    """Generic stopword-density LID over the given per-language tables. Returns a
    language code when density ≥ threshold, else None (unplaceable)."""
    toks = [t for t in re.split(r"[^\w']+", str(text).lower()) if t]
    if len(toks) < 6:
        return None
    best, best_density = None, 0.0
    for lang, sw in tables.items():
        density = sum(1 for t in toks if t in sw) / len(toks)
        if density > best_density:
            best, best_density = lang, density
    return best if best_density >= _LATIN_LID_MIN_DENSITY else None


def _latin_lid(text):
    """Return a Latin-script language code if the text reads confidently as one
    (stopword density ≥ threshold), else None. Density (occurrences / tokens),
    not absolute hits — real Latin is stopword-dense, romanized non-Latin is not.
    None → the caller probes language=ar; a misplace only costs a probe."""
    return _stopword_lid(text, _LATIN_STOPWORDS)


def _cyrillic_lid(text):
    """Cyrillic counterpart of _latin_lid — places real Russian/Ukrainian/
    Bulgarian; fails to place Cyrillic-transliterated Arabic."""
    return _stopword_lid(text, _CYRILLIC_STOPWORDS)


def _looks_confused(transcript, script="Latin"):
    """Deepgram's confusion signature: it did NOT place a language AND a text-LID
    can't place the text as any KNOWN language of its script — the tell for a
    TRANSLITERATED non-native language (Arabic under multi). Two reliable
    signals; the language=ar probe is the confirmation, so an over-fire only
    costs a probe.

    SCRIPT-AWARE (graduation cert finding): Deepgram multi transliterates Arabic
    into Latin OR Cyrillic run-to-run, so the signature reads both — Latin text
    against the Latin stopword tables, Cyrillic against ru/uk/bg. Real Russian
    places by density and never pays the probe.

    NOTE (measured, cert run): Zac's third signal — incoherent per-word tags — is
    NON-DETERMINISTIC (Deepgram tagged the same romanized-Arabic clip ['fr','hi']
    one run, a single language the next), so requiring it MISSED real Arabic. It's
    kept as a LOGGED signal, not a gate. The text-LID + probe carry the detection.
    A real language reads as itself → placeable → no fire; only transliterated
    non-native text (or a tongue outside the stopword tables) reaches the probe."""
    if (transcript.get("detected_language") or "").strip():
        return False  # Deepgram placed a language — trust it
    words = transcript.get("words") or []
    if len(words) < 3:
        return False
    text = " ".join(str(w.get("word") or "") for w in words)
    _lid = _cyrillic_lid if script == "Cyrillic" else _latin_lid
    if _lid(text) is not None:
        return False  # reads as a known language of its script — not transliteration
    _wl = sorted({str(w.get("language") or "").split("-")[0] for w in words} - {""})
    incoherent = len(_wl) >= 2 or bool(set(_wl) & _NONLATIN_LANG_CODES)
    print(f"[arabic-bridge] confusion signature: detected=None + unplaceable-{script} "
          f"(per-word-langs={_wl} incoherent={incoherent}) → probing language=ar", flush=True)
    return True


def _probe_confirms_arabic(source_path):
    """Cheap confirmation: re-transcribe with nova-3 language=ar (verified to
    produce native Arabic script). Confirmed iff it returns a coherent run of
    Arabic-script words. Best-effort — any failure returns (False, None) so the
    caller proceeds unchanged (no worse than today's leak). ~half a cent, only
    on suspect jobs."""
    try:
        if DeepgramClient is None or PrerecordedOptions is None:
            return (False, None)
        dg = DeepgramClient(api_key=os.environ["DEEPGRAM_API_KEY"])
        audio_bytes = prepare_audio_for_deepgram(source_path)
        options = PrerecordedOptions(
            model="nova-3", language="ar", smart_format=True, punctuate=True)
        resp = dg.listen.prerecorded.v("1").transcribe_file(
            {"buffer": audio_bytes, "mimetype": "audio/flac"}, options)
        parsed = _parse_deepgram_response(resp)
        _words = parsed.get("words") or []
        _script = _dominant_script(_words)
        _n = len(_words)
        _conf = (sum(w.get("confidence", 0.0) for w in _words) / _n) if _n else 0.0
        ok = _script == "Arabic" and _n >= 5 and _conf >= 0.3
        print(f"[arabic-bridge] language=ar probe: {_n} words, script={_script}, "
              f"conf={_conf:.2f} → {'ARABIC' if ok else 'not-arabic'}", flush=True)
        return (ok, parsed if ok else None)
    except Exception as _e:
        print(f"[arabic-bridge] probe skipped ({type(_e).__name__})", flush=True)
        return (False, None)


# ── TIER-1 STAGE A: DEEPGRAM MONOLINGUAL ROUTING (Zac 2026-07-28, viral surge) ──────────
# Deepgram `multi` mislabels + under-covers non-English (a 2026-07-28 cert: it tagged Bengali
# and Tamil clips 'hi', and covered them 40-85% short). Deepgram supports many more languages
# in `language=xx` monolingual than in multi. When multi coverage FAILS, probe the monolingual
# models for the arriving-language candidate set and recover the best-coverage NATIVE transcript
# — the exact Arabic-bridge mechanism, generalised past 'ar'.
def _lang_routing_enabled():
    """Flag-gated (PROMPTLY_LANG_ROUTING=1). OFF → the probe never runs (byte-identical)."""
    return os.environ.get("PROMPTLY_LANG_ROUTING", "").strip() == "1"


# Candidate monolingual languages — every Deepgram-supported language that plausibly arrives
# (India is ~67% of the 2026-07-28 surge → all major Indian languages) + the Latin non-English
# arrivals. Probing is PARALLEL, so a wider set costs no extra latency; an unsupported language
# (Deepgram 400s, e.g. pa) just drops out. Selection-by-confidence (below) keeps a wider set safe.
_LANG_ROUTING_CANDIDATES = ("hi", "mr", "bn", "ta", "te", "gu", "ml", "kn", "ur", "pa", "es", "pt")
# The native script each candidate MUST produce (fail-closed: a probe returning the wrong script
# is transliteration/garbage, never accepted — it would render as silent nonsense).
_EXPECTED_SCRIPT_FOR_LANG = {
    "hi": "Devanagari", "mr": "Devanagari", "bn": "Bengali", "ta": "Tamil",
    "te": "Telugu", "gu": "Gujarati", "ml": "Malayalam", "kn": "Kannada",
    "pa": "Gurmukhi", "ur": "Arabic", "ar": "Arabic", "ru": "Cyrillic",
    "es": "Latin", "pt": "Latin", "fr": "Latin", "de": "Latin", "it": "Latin",
}


def _probe_best_language(source_path, candidates, source_duration):
    """Probe Deepgram MONOLINGUAL models (in PARALLEL) and return the transcript that best fits
    the audio. Deepgram multi mislabels, so we probe the whole set, not a detected label. FOUR
    binding rules:
      • PARALLEL — fire every probe concurrently; a rejected user has already waited a full
        render, so sequential probes would stack latency onto exactly the slowest jobs.
      • SELECTION BY CONFIDENCE — a WRONG language phonetically APPROXIMATES the audio and can
        still pass coverage with plausible word counts, so coverage alone mis-selects (measured:
        Bengali beat Hindi on a Hindi clip by 0.1s coverage). The true language scores higher
        Deepgram word CONFIDENCE; select by confidence (word count breaks ties). Negative-control
        certified: a known-Hindi clip must pick hi, not bn/ta.
      • FAIL-CLOSED ON SCRIPT — must produce the language's native script, never transliteration.
      • FONT-BACKED — the native script must render (_script_reaches_render), else it is tofu;
        skip (Stage B / translation handles those).
    Only coverage-PASSING candidates are eligible (recovery must actually fix the failing gate).
    Returns (lang, parsed_transcript, unworded_s) for the best, or (None, None, None)."""
    import concurrent.futures as _cf

    def _probe_one(_lg):
        try:
            return (_lg, transcribe_audio(source_path, language=_lg))
        except Exception as _e:
            print(f"[lang-routing] probe {_lg} failed ({type(_e).__name__}) — skip", flush=True)
            return (_lg, None)

    _raw = {}
    with _cf.ThreadPoolExecutor(max_workers=min(len(candidates), 12)) as _ex:
        for _lg, _tx in _ex.map(_probe_one, candidates):
            _raw[_lg] = _tx

    _scored = []
    for _lg in candidates:
        _tx = _raw.get(_lg)
        _w = (_tx or {}).get("words") or [] if _tx else []
        if len(_w) < 5:
            continue
        _sc = _dominant_script(_w)
        _expected = _EXPECTED_SCRIPT_FOR_LANG.get(_lg)
        if _expected and _sc != _expected:
            continue  # transliteration / wrong script → fail-closed
        if not _script_reaches_render(_sc):
            continue  # no caption font → would render tofu
        try:
            _ok, _cov = _transcription_coverage_check(source_path, _w, source_duration)
        except Exception:
            continue
        if not _ok:
            continue  # recovery must PASS coverage
        _conf = (sum(float(_x.get("confidence") or 0.0) for _x in _w) / len(_w)) if _w else 0.0
        _scored.append({"lang": _lg, "tx": _tx, "words": len(_w), "conf": round(_conf, 3),
                        "unworded": _cov.get("unworded_speech_s"), "script": _sc})
    if not _scored:
        return (None, None, None)
    _scored.sort(key=lambda s: (s["conf"], s["words"]), reverse=True)
    _best = _scored[0]
    print(f"[lang-routing] scored {[(s['lang'], s['words'], s['conf']) for s in _scored]} → "
          f"selected {_best['lang']} (conf={_best['conf']}, {_best['words']}w, {_best['script']})", flush=True)
    return (_best["lang"], _best["tx"], _best["unworded"])


# Per-script GRADUATION (Zac 2026-07-28): route only languages whose script has been proven end-
# to-end (one sample rendered → frontend gates tofu/fit/timing/coverage). Hindi (Devanagari) is
# certified; others graduate one at a time. Env-overridable (PROMPTLY_ROUTE_LANGS="hi,bn,ta").
_GRADUATED_ROUTE_LANGS_DEFAULT = frozenset({"hi"})


def _graduated_route_langs():
    _raw = os.environ.get("PROMPTLY_ROUTE_LANGS")
    if _raw is None:
        return _GRADUATED_ROUTE_LANGS_DEFAULT
    return frozenset(c.strip() for c in _raw.split(",") if c.strip())


def _identify_language_gemini(source_path):
    """INDEPENDENT spoken-language identification via Gemini. Acoustic probe-and-select can't
    separate languages — Deepgram confidence is cross-model-incomparable (Gujarati out-scored
    Bengali on a Bengali clip) and Hindi/Urdu are the same spoken language. Gemini hears the audio
    AND reads on-screen text/context, so it reliably distinguishes DISTINCT languages. Returns an
    ISO 639-1 code or None. Best-effort — any failure returns None → the caller falls to Stage B."""
    try:
        if genai_types is None:
            return None
        _client = _get_genai_client()
        _audio = prepare_audio_for_deepgram(source_path)
        _prompt = ("Identify the PRIMARY spoken language of this audio. Return JSON "
                   '{"language": "<ISO 639-1 two-letter lowercase code>"} — e.g. hi, bn, ta, te, '
                   'gu, kn, mr, ur, es, pt, en. For Hindi/Urdu ambiguity default to hi.')
        # NO max_output_tokens cap — GEMINI_MODEL is a thinking model; a tiny cap is spent on
        # thinking and yields an EMPTY answer. JSON mime + schema forces a clean code.
        _resp = _client.models.generate_content(
            model=GEMINI_MODEL,
            contents=[genai_types.Part.from_bytes(data=_audio, mime_type="audio/flac"), _prompt],
            config=genai_types.GenerateContentConfig(
                temperature=0.0, response_mime_type="application/json"))
        _txt = (_resp.text or "").strip()
        try:
            _code = str(json.loads(_txt or "{}").get("language") or "").strip().lower()
        except Exception:
            _code = "".join(ch for ch in _txt.lower() if ch.isalpha())
        _code = "".join(ch for ch in _code if ch.isalpha())[:2]
        if len(_code) == 2:
            print(f"[lang-id] Gemini identified language={_code}", flush=True)
            return _code
        print(f"[lang-id] Gemini returned no usable code (raw={_txt[:60]!r}) — Stage B", flush=True)
    except Exception as _e:
        print(f"[lang-id] Gemini language-ID failed ({type(_e).__name__}: {str(_e)[:80]}) — Stage B", flush=True)
    return None


def _route_language_via_gemini(source_path, source_duration):
    """SAFE Stage A: Gemini IDs the language, then route to that ONE Deepgram monolingual model —
    no cross-model acoustic selection. Guards: GRADUATED (script proven end-to-end), FAIL-CLOSED
    ON SCRIPT (native or bail), FONT-BACKED, SELECTION (recovered transcript must PASS coverage —
    a Gemini mis-ID that transcribes poorly is caught here). Returns (lang, transcript, unworded_s)
    or (None, None, None) → Stage B."""
    _lang = _identify_language_gemini(source_path)
    if not _lang:
        return (None, None, None)
    if _lang == "en" or _lang not in _graduated_route_langs():
        print(f"[lang-routing] language={_lang} not graduated (routable={sorted(_graduated_route_langs())}) "
              f"— hold for Stage B / graduation", flush=True)
        return (None, None, None)
    try:
        _tx = transcribe_audio(source_path, language=_lang)
    except Exception as _e:
        print(f"[lang-routing] Deepgram language={_lang} unsupported ({type(_e).__name__}) — Stage B", flush=True)
        return (None, None, None)
    _w = (_tx or {}).get("words") or []
    if len(_w) < 5:
        return (None, None, None)
    _sc = _dominant_script(_w)
    _expected = _EXPECTED_SCRIPT_FOR_LANG.get(_lang)
    if _expected and _sc != _expected:
        print(f"[lang-routing] language={_lang} produced {_sc}≠{_expected} — bail (fail-closed)", flush=True)
        return (None, None, None)
    if not _script_reaches_render(_sc):
        print(f"[lang-routing] language={_lang} script={_sc} has no caption font — Stage B/translate", flush=True)
        return (None, None, None)
    try:
        _ok, _cov = _transcription_coverage_check(source_path, _w, source_duration)
    except Exception:
        return (None, None, None)
    if not _ok:
        print(f"[lang-routing] language={_lang} still fails coverage ({_cov.get('unworded_speech_s')}s) "
              f"— likely a Gemini mis-ID; Stage B", flush=True)
        return (None, None, None)
    _u = _cov.get("unworded_speech_s")
    print(f"[lang-routing] Gemini-ID→Deepgram language={_lang}: {len(_w)}w {_sc} unworded={_u}s — RECOVERED", flush=True)
    return (_lang, _tx, _u)


def _dominant_script(words):
    """Dominant Unicode script of a Deepgram word list (dicts with 'word').
    Counts letter codepoints by script range; neutral chars (digits, punct,
    space) don't count. Returns the script with the most letters, or 'Latin'
    when there are no classifiable letters (a digits-only transcript is safe —
    ASCII renders everywhere). Deterministic, no I/O."""
    counts = {}
    for w in (words or []):
        _t = w.get("word", "") if isinstance(w, dict) else str(w)
        for ch in _t:
            cp = ord(ch)
            if cp < 0x0250 and not (0x0041 <= cp <= 0x024F):
                continue  # ASCII digits/punct/control — neutral
            for name, ranges in _SCRIPT_RANGES:
                if any(lo <= cp <= hi for lo, hi in ranges):
                    counts[name] = counts.get(name, 0) + 1
                    break
    if not counts:
        return "Latin"
    return max(counts.items(), key=lambda kv: kv[1])[0]


